namespace AuthorizationAuthority.Domain.Features.PlatformOperators;

/// <summary>
/// C8 onboarding (C-104): a request to create one organization with its initial owners. Platform-scoped and Authority-owned. The
/// organization id and every owner's user id are generated by the Authority when the request is created and never change; the
/// request is immutable after creation (no revisions, D8-49 deferred): a different organization or owner set is a new request.
/// Nothing exists in the organization tables until <see cref="OrganizationOnboardingStates.Initialized"/>.
/// </summary>
public sealed class OrganizationOnboardingRequest
{
    public Guid OrganizationOnboardingRequestId { get; set; }

    /// <summary>The organization id the Authority generated for this request (unique across all requests and organizations).</summary>
    public Guid ReservedOrganizationId { get; set; }

    public string OrganizationDisplayName { get; set; } = string.Empty;

    /// <summary>NFKC, case-folded, whitespace collapsed; unique among requests that are not closed (partial unique index).</summary>
    public string OrganizationNormalizedName { get; set; } = string.Empty;

    /// <summary>The single identity issuer of every initial owner (the organization's derived issuer afterwards).</summary>
    public string IdentityIssuerUri { get; set; } = string.Empty;

    /// <summary>One of <see cref="OrganizationOnboardingStates"/>. Expiry is a time comparison, recorded as Expired when touched.</summary>
    public string OnboardingStateName { get; set; } = OrganizationOnboardingStates.PendingApproval;

    public string RequestReasonText { get; set; } = string.Empty;

    public Guid CreatedByPlatformOperatorId { get; set; }

    /// <summary>The creating operator's idempotency key; unique per operator.</summary>
    public string CreateIdempotencyKey { get; set; } = string.Empty;

    /// <summary>SHA-256 of the creating operator's canonical input; a retry with the same key and different input is a conflict.</summary>
    public byte[] CreateRequestDigest { get; set; } = [];

    /// <summary>The canonical statement both approving operators sign (stored as text, never jsonb, so its digest is stable).</summary>
    public string OnboardingStatementJson { get; set; } = string.Empty;

    public byte[] OnboardingStatementSha256 { get; set; } = [];

    /// <summary>Provider key name the custody step must create (org-&lt;id&gt;-row-integrity-v1).</summary>
    public string IntegrityKeyName { get; set; } = string.Empty;

    public DateTimeOffset RequestCreatedOn { get; set; }

    public DateTimeOffset RequestExpiresOn { get; set; }

    public DateTimeOffset? OnboardingApprovedOn { get; set; }

    /// <summary>Set at approval: initialization must happen before this instant.</summary>
    public DateTimeOffset? KeyCustodyExpiresOn { get; set; }

    public DateTimeOffset? OnboardingInitializedOn { get; set; }

    public Guid? InitializedByPlatformOperatorId { get; set; }

    public Guid? InitializedBySecurityCommandId { get; set; }

    public DateTimeOffset? OnboardingClosedOn { get; set; }

    public Guid? ClosedByPlatformOperatorId { get; set; }

    /// <summary>One of <see cref="OrganizationOnboardingClosureReasons"/> once closed.</summary>
    public string? OnboardingClosureReasonName { get; set; }

    public string? ClosureJustificationText { get; set; }

    /// <summary>Last refused initialization (for display; never a decision input).</summary>
    public string? LastInitializationFailureCode { get; set; }

    public DateTimeOffset? LastInitializationFailureOn { get; set; }

    /// <summary>Optimistic concurrency: incremented on every change of this row.</summary>
    public long OnboardingRowRevision { get; set; } = 1;
}

/// <summary>One initial owner of an onboarding request. Immutable; the user id is generated by the Authority.</summary>
public sealed class OrganizationOnboardingOwner
{
    public Guid OrganizationOnboardingOwnerId { get; set; }

    public Guid OrganizationOnboardingRequestId { get; set; }

    public int OwnerOrdinalNumber { get; set; }

    public Guid ReservedAuthorityUserId { get; set; }

    public string OwnerIssuerUri { get; set; } = string.Empty;

    public string OwnerSubjectIdentifier { get; set; } = string.Empty;

    /// <summary>Display only, never an identifier.</summary>
    public string OwnerDisplayNameHint { get; set; } = string.Empty;

    /// <summary>One of <see cref="OnboardingVerificationMethods"/> (V2 operator attestation; production also needs V3 proof of control).</summary>
    public string OwnerVerificationMethodName { get; set; } = string.Empty;

    public string OwnerVerificationReferenceText { get; set; } = string.Empty;
}

/// <summary>One operator's approval of one onboarding request. Evidence only; the second valid approval by a different operator approves the request.</summary>
public sealed class OrganizationOnboardingApproval
{
    public Guid OrganizationOnboardingApprovalId { get; set; }

    public Guid OrganizationOnboardingRequestId { get; set; }

    public Guid PlatformOperatorId { get; set; }

    public byte[] ApprovalStatementSha256 { get; set; } = [];

    public string ApprovalJustificationText { get; set; } = string.Empty;

    public string ApprovalEvidenceKindName { get; set; } = string.Empty;

    public byte[] ApprovalEvidenceSha256 { get; set; } = [];

    public string ApprovalEvidenceIdentifier { get; set; } = string.Empty;

    public DateTimeOffset ApprovalRecordedOn { get; set; }

    /// <summary>One of <see cref="OnboardingApprovalStates"/>. Closed rows never change again.</summary>
    public string ApprovalStateName { get; set; } = OnboardingApprovalStates.Valid;

    public DateTimeOffset? ApprovalClosedOn { get; set; }

    public string? ApprovalClosureReasonName { get; set; }
}

public static class OrganizationOnboardingStates
{
    public const string PendingApproval = "PendingApproval";
    public const string AwaitingKeyCustody = "AwaitingKeyCustody";
    public const string Initialized = "Initialized";
    public const string Rejected = "Rejected";
    public const string Cancelled = "Cancelled";
    public const string Expired = "Expired";

    public static readonly IReadOnlyList<string> Open = [PendingApproval, AwaitingKeyCustody];

    public static bool IsClosed(string state) => state is Rejected or Cancelled or Expired;
}

public static class OrganizationOnboardingClosureReasons
{
    public const string Rejected = "RejectedByOperator";
    public const string Cancelled = "CancelledByOperator";
    public const string ApprovalWindowExpired = "ApprovalWindowExpired";
    public const string KeyCustodyWindowExpired = "KeyCustodyWindowExpired";
}

public static class OnboardingApprovalStates
{
    public const string Valid = "Valid";
    public const string Consumed = "Consumed";
    public const string Withdrawn = "Withdrawn";
    public const string Invalidated = "Invalidated";
}

public static class OnboardingVerificationMethods
{
    public const string SupportCallback = "SupportCallback";
    public const string ContractSignatory = "ContractSignatory";
    public const string CustomerAdministratorAttestation = "CustomerAdministratorAttestation";

    public static readonly IReadOnlyList<string> All = [SupportCallback, ContractSignatory, CustomerAdministratorAttestation];
}
